function [Nperpp,Nperpm,Kxyz,ep_xyz,em_xyz,ep_pmz,em_pmz,ep_ppk,em_ppk] = colddisp_dke_jd(Npar,omega_rf,ne,zni,zZi,zmi,Bfield);%% Solve the dispersion equations in the linear cold plasma model.%% by J. Decker 05/02/03%qe = 1.6022e-19;%Electron charge (C)me = 9.1094e-31;%Electron rest mass (Kg)mp = 1.6726e-27;%Proton rest mass (Kg)e0 = 8.8542e-12;%Free space permeability (F/m)%ns = [ne;zni(:)];qs = qe*[-1;zZi(:)];ms = [me;mp*zmi(:)];%wps = sqrt(ns.*qs.^2/e0./ms);wcs = qs*Bfield./ms;%ps = wps/omega_rf;ys = wcs/omega_rf;%%   Dielectric tensor elements%Kperp = 1 - sum(ps.^2./(1 - ys.^2));Kpar = 1 - sum(ps.^2);Kxy = sum(ps.^2.*ys./(1 - ys.^2));%Kxyz = [Kperp,-i*Kxy,0;i*Kxy,Kperp,0;0,0,Kpar];%%   Dispersion relation%A = Kperp;B = (Npar^2 - Kperp)*(Kperp + Kpar) + Kxy^2;C = Kpar*((Npar^2 - Kperp)^2 - Kxy^2);%Nperpp = sqrt((-B + sqrt(B^2-4*A*C))/(2*A));Nperpm = sqrt((-B - sqrt(B^2-4*A*C))/(2*A));%Nxyzp = [Nperpp;0;Npar];         Nxyzm = [Nperpm;0;Npar];         %%   Dispersion tensor for + root%Dxyzp = Nxyzp*Nxyzp' - sum(Nxyzp.^2)*diag([1,1,1]) + Kxyz;%%   Dispersion tensor for - root%Dxyzm = Nxyzm*Nxyzm' - sum(Nxyzm.^2)*diag([1,1,1]) + Kxyz;%%   Eigenvectors%[Evecp,Evalp] = eig(Dxyzp);[Evecm,Evalm] = eig(Dxyzm);%Eval0p = diag(Evalp); %eigenvaluesEval0m = diag(Evalm); %eigenvalues%jp = find(abs(Eval0p) == min(abs(Eval0p))); %select eigenvalue lambda=0 jm = find(abs(Eval0m) == min(abs(Eval0m))); %select eigenvalue lambda=0 %Evec0p = Evecp(:,jp); %eigenvectorEvec0m = Evecm(:,jm); %eigenvector%%   Polarization vectors%ep_xyz = Evec0p./norm(Evec0p); %xyzem_xyz = Evec0m./norm(Evec0m);%M_xypm = [1,i,0;1,-i,0;0,0,sqrt(2)]/sqrt(2);%ep_pmz = M_xypm*ep_xyz; %pmzem_pmz = M_xypm*em_xyz;%cp = Npar/norm(Nxyzp);sp = Nperpp/norm(Nxyzp); cm = Npar/norm(Nxyzm);sm = Nperpm/norm(Nxyzm); %Mp_xypk = [cp,0,-sp;0,1,0;sp,0,cp];Mm_xypk = [cm,0,-sm;0,1,0;sm,0,cm];%ep_ppk = Mp_xypk*ep_xyz; %ppkem_ppk = Mm_xypk*em_xyz;